#!/usr/bin/env bash
#
# Build and run the host-side simulation of the QNX demo.
#
# Produces examples/logs/sim_flawed_slog2.txt, a real log generated by the
# real C service sources, then analyses it with the RTArchitect CLI.
#
# NOTE: this is a host-side simulation, not QNX.  It validates the C sources,
# the RTARCH log format and the analysis pipeline end to end.

set -euo pipefail

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
REPO="$(cd "$ROOT/../.." && pwd)"
cd "$ROOT"

make clean >/dev/null
make

LOG="$REPO/examples/logs/sim_flawed_slog2.txt"
mkdir -p "$(dirname "$LOG")"

echo "Running simulation..."
./rtarch_sim > "$LOG" 2>&1

echo "Log written: $LOG"
echo "RTARCH events: $(grep -c RTARCH "$LOG")"
echo

cd "$REPO"
"${PYTHON:-.venv/bin/python}" -m rtarch analyze "$LOG" \
  --scenario scenarios/brake_demo.json \
  --output examples/reports/sim_flawed_report.html
